ALTER POLICY "feedback_settings readable by everyone" ON public.feedback_settings TO authenticated USING (public.has_role(auth.uid(), 'student'::public.app_role) OR public.has_role(auth.uid(), 'admin'::public.app_role));
ALTER POLICY "feedback_media readable by everyone" ON public.feedback_media TO authenticated USING (enabled AND (public.has_role(auth.uid(), 'student'::public.app_role) OR public.has_role(auth.uid(), 'admin'::public.app_role)));
ALTER POLICY "Authenticated view app release" ON public.app_release TO authenticated USING (NULLIF(file_path, '') IS NOT NULL AND (public.has_role(auth.uid(), 'student'::public.app_role) OR public.has_role(auth.uid(), 'admin'::public.app_role)));
ALTER POLICY "Authenticated view subjects" ON public.subjects TO authenticated USING (public.has_role(auth.uid(), 'student'::public.app_role) OR public.has_role(auth.uid(), 'admin'::public.app_role));
ALTER POLICY "Authenticated view performance" ON public.performance TO authenticated USING (public.has_role(auth.uid(), 'student'::public.app_role) OR public.has_role(auth.uid(), 'admin'::public.app_role));
ALTER POLICY "Authenticated view pdfs" ON public.pdfs TO authenticated USING (public.has_role(auth.uid(), 'student'::public.app_role) OR public.has_role(auth.uid(), 'admin'::public.app_role));
ALTER POLICY "app_intro readable by everyone" ON public.app_intro TO anon, authenticated USING (enabled AND NULLIF(file_path, '') IS NOT NULL);
ALTER POLICY "Authenticated view chapters" ON public.chapters TO authenticated USING (public.has_role(auth.uid(), 'student'::public.app_role) OR public.has_role(auth.uid(), 'admin'::public.app_role));
ALTER POLICY "branding read for authenticated" ON storage.objects TO authenticated USING (bucket_id = 'branding' AND (public.has_role(auth.uid(), 'admin'::public.app_role) OR EXISTS (SELECT 1 FROM public.app_intro i WHERE i.enabled AND i.file_path = objects.name) OR EXISTS (SELECT 1 FROM public.feedback_media m WHERE m.enabled AND m.file_path = objects.name AND public.has_role(auth.uid(), 'student'::public.app_role))));
ALTER POLICY "branding read for anon" ON storage.objects TO anon USING (bucket_id = 'branding' AND EXISTS (SELECT 1 FROM public.app_intro i WHERE i.enabled AND i.file_path = objects.name));
ALTER POLICY "Authenticated read app releases" ON storage.objects TO authenticated USING (bucket_id = 'app-releases' AND (public.has_role(auth.uid(), 'admin'::public.app_role) OR (public.has_role(auth.uid(), 'student'::public.app_role) AND EXISTS (SELECT 1 FROM public.app_release r WHERE r.file_path = objects.name))));
ALTER POLICY "Authenticated read study materials" ON storage.objects TO authenticated USING (bucket_id = 'study-materials' AND (public.has_role(auth.uid(), 'admin'::public.app_role) OR (public.has_role(auth.uid(), 'student'::public.app_role) AND (EXISTS (SELECT 1 FROM public.pdfs p WHERE p.file_path = objects.name) OR EXISTS (SELECT 1 FROM public.performance p WHERE p.image_path = objects.name)))));